-- Clients are recognized by their mobile phone; email becomes optional (ADR-012).

-- AlterTable
ALTER TABLE "Client" ALTER COLUMN "email" DROP NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "Client_phone_key" ON "Client"("phone");

-- Manual (not generated by Prisma): phones are stored in E.164 ("+59899123456"),
-- so "099 123 456" and "+598 99 123 456" can never become two different clients.
ALTER TABLE "Client" ADD CONSTRAINT "Client_phone_e164_check"
  CHECK ("phone" ~ '^\+[1-9][0-9]{6,14}$');
